Create Patient.code:
// Create a Patient in the NDR from an EMR client record.
create(
  // 1) Resource type.
  'Patient',
  // 2) Resource data (no id or resourceType needed).
  {
    identifier: [
      // Facility medical record number.
      { system: 'http://moh.gov.et/fhir/hiv/identifier/MRN', value: $.data.mrn },
    ],
    name: [{ use: 'official', family: $.data.fatherName, given: [$.data.firstName] }],
    gender: $.data.sex, // 'male' | 'female'
    birthDate: $.data.dateOfBirth, // 'YYYY-MM-DD'
    managingOrganization: { reference: `Organization/${$.data.facilityId}` },
  }
);

Create Encounter.code:
// Create an Encounter for an ART follow-up visit.
create('Encounter', {
  status: 'finished',
  class: {
    system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode',
    code: 'AMB',
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  serviceProvider: { reference: `Organization/${$.data.facilityId}` },
  period: { start: $.data.visitDate },
});

Create Viral Load Observation.code:
// Create an HIV-1 viral load result Observation.
create('Observation', {
  status: 'final',
  code: {
    coding: [{ system: 'http://loinc.org', code: '25836-8', display: 'HIV 1 RNA [#/volume] (viral load)' }],
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  encounter: { reference: `Encounter/${$.data.encounterId}` },
  effectiveDateTime: $.data.sampleCollectedAt,
  valueQuantity: {
    value: $.data.viralLoad,
    unit: 'copies/mL',
    system: 'http://unitsofmeasure.org',
    code: '{copies}/mL',
  },
});

Create CD4 Count Observation.code:
// Create a CD4 count Observation.
create('Observation', {
  status: 'final',
  code: {
    coding: [{ system: 'http://loinc.org', code: '24467-3', display: 'CD4 cells [#/volume] in Blood' }],
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  effectiveDateTime: $.data.resultDate,
  valueQuantity: { value: $.data.cd4Count, unit: 'cells/uL' },
});

Create HIV Diagnosis Condition.code:
// Create a Condition for a confirmed HIV diagnosis.
create('Condition', {
  clinicalStatus: {
    coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-clinical', code: 'active' }],
  },
  verificationStatus: {
    coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-ver-status', code: 'confirmed' }],
  },
  code: {
    coding: [{ system: 'http://snomed.info/sct', code: '86406008', display: 'Human immunodeficiency virus infection' }],
  },
  subject: { reference: `Patient/${$.data.patientId}` },
  onsetDateTime: $.data.diagnosisDate,
});

Create Facility Organization.code:
// Create an Organization for a reporting health facility.
create('Organization', {
  identifier: [{ system: 'http://moh.gov.et/fhir/hiv/identifier/facility', value: $.data.facilityCode }],
  name: $.data.facilityName,
  active: true,
});

Create Practitioner.code:
// Create a Practitioner for the clinician who saw the patient.
create('Practitioner', {
  name: [{ family: $.data.lastName, given: [$.data.firstName] }],
  telecom: [{ system: 'phone', value: $.data.phone }],
});
